"""
INTRSPOT BI Agent API — FastAPI Backend
"""
import os
import io
import json
import pandas as pd
from fastapi import FastAPI, UploadFile, File, Form, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
from dotenv import load_dotenv
from agent import BIAgent

load_dotenv()

app = FastAPI(title="INTRSPOT BI Agent", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# ── Load API key ───────────────────────────────────────────────────────────────
API_KEY = os.getenv("ANTHROPIC_API_KEY", "")


def load_dataframe(file: UploadFile) -> pd.DataFrame:
    """Load Excel or CSV into DataFrame"""
    content = file.file.read()
    filename = file.filename or ""
    if filename.endswith(".csv"):
        return pd.read_csv(io.BytesIO(content))
    elif filename.endswith((".xlsx", ".xls")):
        return pd.read_excel(io.BytesIO(content))
    else:
        # Try CSV first, then Excel
        try:
            return pd.read_csv(io.BytesIO(content))
        except Exception:
            return pd.read_excel(io.BytesIO(content))


# ── Routes ─────────────────────────────────────────────────────────────────────

@app.get("/")
def root():
    return {"status": "INTRSPOT BI Agent is running 🚀"}


@app.get("/health")
def health():
    return {"status": "ok", "api_key_set": bool(API_KEY)}


@app.post("/analyze")
async def analyze(
    file: UploadFile = File(...),
    question: str = Form(default="حلّل هذه البيانات وأعطني أهم الرؤى مع لوحة تحكم كاملة"),
    language: str = Form(default="ar"),
    output_format: str = Form(default="both"),  # "powerbi", "tableau", "both", "charts"
):
    """
    Main endpoint: upload file + question → BI Agent analyzes and returns results
    """
    if not API_KEY or API_KEY == "your_api_key_here":
        raise HTTPException(status_code=500, detail="ANTHROPIC_API_KEY not configured")

    # Load data
    try:
        df = load_dataframe(file)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read file: {str(e)}")

    if df.empty:
        raise HTTPException(status_code=400, detail="File is empty")

    # Build full prompt
    format_instruction = {
        "powerbi": "Generate Power BI DAX measures and M Query. ",
        "tableau": "Generate Tableau Calculated Fields. ",
        "both": "Generate both Power BI and Tableau code. ",
        "charts": "Focus on charts and visualizations. ",
    }.get(output_format, "")

    lang_instruction = "Respond in Arabic. " if language == "ar" else "Respond in English. "
    full_question = f"{lang_instruction}{format_instruction}{question}"

    # Run agent
    agent = BIAgent(api_key=API_KEY)
    steps_log = []

    def on_step(step_type, content):
        steps_log.append({"type": step_type, "content": content if isinstance(content, str) else json.dumps(content, ensure_ascii=False)})

    result = agent.run(full_question, df, on_step=on_step)

    return JSONResponse({
        "success": True,
        "answer": result["answer"],
        "charts": result["charts"],  # list of {title, data: base64_png}
        "steps": steps_log,
        "dataset_info": {
            "rows": int(df.shape[0]),
            "columns": int(df.shape[1]),
            "column_names": df.columns.tolist(),
        }
    })


@app.post("/quick-stats")
async def quick_stats(file: UploadFile = File(...)):
    """Fast endpoint: just return dataset overview without AI"""
    try:
        df = load_dataframe(file)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))

    import numpy as np
    numeric = df.select_dtypes(include=np.number)

    return {
        "rows": int(df.shape[0]),
        "columns": int(df.shape[1]),
        "column_names": df.columns.tolist(),
        "numeric_columns": numeric.columns.tolist(),
        "text_columns": df.select_dtypes(include="object").columns.tolist(),
        "nulls": df.isnull().sum().to_dict(),
        "sample": df.head(5).to_dict(orient="records"),
        "numeric_summary": numeric.describe().round(2).to_dict() if not numeric.empty else {},
    }

